INSERT INTO `templates` (`id`, `title`, `description`, `sections`, `is_active`, `created_by`, `created_by_name`, `created_at`, `updated_at`, `standard_key`) VALUES ('6e54862b-1fa3-43e0-90d5-4bb6bfa1e9c9','Audit logistique — Déchargement de containers importés','Grille de contrôle standard pour le déchargement des containers importés : contrôle documentaire avant ouverture, inspection de l\'état général, comptage contradictoire et DLC, procédure en cas de non-conformité. Dupliquez-le pour créer un nouveau formulaire à partir de cette base.','[{\"id\":\"993b1ab8-b007-4055-b7d1-63185a6cdd24\",\"label\":\"Contrôle documentaire (avant ouverture)\",\"questions\":[{\"id\":\"d6db4661-8210-477a-a604-2504e8653b4e\",\"text\":\"Le Bill of Lading est-il conforme et disponible ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"99b0e764-89aa-49b2-8c4e-106e536e52d0\",\"text\":\"Précisez l\'anomalie constatée sur le Bill of Lading\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"d6db4661-8210-477a-a604-2504e8653b4e\",\"triggerValues\":[\"no\"]}},{\"id\":\"d455976c-dba8-4054-9822-379582c2e7fb\",\"text\":\"Le certificat sanitaire est-il conforme et disponible ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"dae6d987-4883-497e-a0ec-98971f6a7485\",\"text\":\"Précisez l\'anomalie constatée sur le certificat sanitaire\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"d455976c-dba8-4054-9822-379582c2e7fb\",\"triggerValues\":[\"no\"]}},{\"id\":\"b22235ae-ac9a-4d36-a9d7-76dc8d623a5b\",\"text\":\"Le certificat d\'origine est-il conforme et disponible ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"975f2932-5694-4172-bd62-30c3acee56f7\",\"text\":\"Précisez l\'anomalie constatée sur le certificat d\'origine\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"b22235ae-ac9a-4d36-a9d7-76dc8d623a5b\",\"triggerValues\":[\"no\"]}},{\"id\":\"829a1c40-c3c2-4590-adcd-78f91ec916ac\",\"text\":\"Le Packing List est-il conforme et disponible ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"13f695c1-bdda-4ff4-a61b-86bb7417be15\",\"text\":\"Précisez l\'anomalie constatée sur le Packing List\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"829a1c40-c3c2-4590-adcd-78f91ec916ac\",\"triggerValues\":[\"no\"]}},{\"id\":\"cca6457d-458f-4c2a-98ea-7cf918b9009f\",\"text\":\"Autres documents contrôlés (facture, etc.) — précisez lesquels et leur conformité\",\"type\":\"TEXT\",\"weight\":1,\"required\":false},{\"id\":\"a44e5b70-c320-46d6-bf37-83c605742611\",\"text\":\"Existe-t-il un plombage identifiable et numéroté ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"75a8b2c5-f2da-417f-a678-34298e5e3a1b\",\"text\":\"Précisez l\'anomalie constatée (absence de plombage, numéro illisible…)\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"a44e5b70-c320-46d6-bf37-83c605742611\",\"triggerValues\":[\"no\"]}},{\"id\":\"5cc38f23-8a8c-4290-9e5f-74ca98735cd5\",\"text\":\"Numéro du plombage relevé\",\"type\":\"TEXT\",\"weight\":1,\"required\":false}]},{\"id\":\"d8a789a5-fbb5-4c18-aea8-f582be898d17\",\"label\":\"Inspection de l\'état général du container\",\"questions\":[{\"id\":\"a0fcc094-fde0-4024-8169-51ec45cbfa28\",\"text\":\"Le container est-il intact (absence d\'ouvertures ou de fuites) ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"a416e71f-3369-480c-992c-befbc20f951c\",\"text\":\"Précisez l\'ouverture ou la fuite constatée\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"a0fcc094-fde0-4024-8169-51ec45cbfa28\",\"triggerValues\":[\"no\"]}},{\"id\":\"1f1b6681-7ac1-4ecf-9f7b-c453e49d0c04\",\"text\":\"L\'ouverture des portes du container ne révèle-t-elle aucune anomalie ou suspicion ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"d032e75d-3381-40f2-8859-1c4dbd7a561e\",\"text\":\"Précisez l\'anomalie ou la suspicion constatée\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"1f1b6681-7ac1-4ecf-9f7b-c453e49d0c04\",\"triggerValues\":[\"no\"]}},{\"id\":\"139407b2-6973-4e03-b074-9522a9064e6c\",\"text\":\"Le contrôle visuel initial confirme-t-il qu\'aucun carton ou sac n\'est ouvert ou endommagé ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"04c3ef21-cd86-496b-8c2b-965c87a05f5e\",\"text\":\"Précisez les cartons/sacs ouverts ou endommagés constatés\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"139407b2-6973-4e03-b074-9522a9064e6c\",\"triggerValues\":[\"no\"]}}]},{\"id\":\"b04905cd-876f-439c-8abe-492b61e96fac\",\"label\":\"Opérations de déchargement et traçabilité\",\"questions\":[{\"id\":\"85537d32-f48d-4d75-833e-247b3aee6485\",\"text\":\"Le comptage contradictoire correspond-il au Packing List (et aux autres documents : facture, Bill of Lading) ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"14084464-a29b-4301-bcdd-92bfd7b1d78a\",\"text\":\"Précisez l\'écart constaté (référence, quantité)\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"85537d32-f48d-4d75-833e-247b3aee6485\",\"triggerValues\":[\"no\"]}},{\"id\":\"603948d4-9bff-4cc1-9afe-df24951d3209\",\"text\":\"Écart de quantité constaté (unités)\",\"type\":\"NUMBER\",\"weight\":1,\"required\":false,\"dependsOn\":{\"questionId\":\"85537d32-f48d-4d75-833e-247b3aee6485\",\"triggerValues\":[\"no\"]}},{\"id\":\"76176161-031a-4f95-89fe-69b05f8b2972\",\"text\":\"Le contrôle des DLC par échantillonnage est-il conforme ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"7f2a340b-1670-404f-b9f2-73d9f655da77\",\"text\":\"Précisez les références et DLC non conformes constatées\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"76176161-031a-4f95-89fe-69b05f8b2972\",\"triggerValues\":[\"no\"]}}]},{\"id\":\"54e9a070-ce90-47b4-b529-9dbbff87cf36\",\"label\":\"Procédure en cas de non-conformité\",\"questions\":[{\"id\":\"3fde8c36-cb31-447d-b419-28992df798e7\",\"text\":\"Une non-conformité a-t-elle été détectée durant cet audit ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"d2a341d6-39f7-45cc-86c3-d3f890c441c9\",\"text\":\"Description de la non-conformité constatée\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"3fde8c36-cb31-447d-b419-28992df798e7\",\"triggerValues\":[\"yes\"]}},{\"id\":\"19a3eefe-f65c-4ff8-b906-141b8705a011\",\"text\":\"Des photographies horodatées ont-elles été prises (scellé cassé, marchandise endommagée, container peu rempli…) ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"3fde8c36-cb31-447d-b419-28992df798e7\",\"triggerValues\":[\"yes\"]}},{\"id\":\"24ab0b0d-37c4-4ce4-bc70-6c6956da844f\",\"text\":\"Le lot a-t-il été bloqué en zone de quarantaine (non-conformité majeure) ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"3fde8c36-cb31-447d-b419-28992df798e7\",\"triggerValues\":[\"yes\"]}},{\"id\":\"8b7d1888-8a81-415c-b922-a40a0343c749\",\"text\":\"Une fiche de non-conformité a-t-elle été émise et transmise à la Direction des Achats ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true,\"dependsOn\":{\"questionId\":\"3fde8c36-cb31-447d-b419-28992df798e7\",\"triggerValues\":[\"yes\"]}}]}]',0,'SUP-0001','Administrateur Audit','2026-10-21T10:30:11.473Z','2026-10-21T10:30:11.473Z','container'),
('89f04129-9973-4214-9e46-b2f1d0f2fb40','Audit industriel — Usine S2I','Trame standard pour les audits usine : ventes, ordres de fabrication, machines/moules, matières premières, rebuts, recouvrement, RH et sécurité. Dupliquez-le pour créer un nouveau formulaire à partir de cette base.','[{\"id\":\"2a2ab475-b15d-4e1f-a466-47a6721f98bb\",\"label\":\"Ventes et chiffre d\'affaires\",\"questions\":[{\"id\":\"564bbde3-029d-4a55-86a6-2d2c7d92b06a\",\"text\":\"L\'évolution du chiffre d\'affaires du mois est-elle conforme aux objectifs ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"c09d9dec-b190-4914-bc8a-3dbb77760d7b\",\"text\":\"Précisez les écarts constatés et leurs causes (perte de clients, nouveaux clients…)\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"564bbde3-029d-4a55-86a6-2d2c7d92b06a\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"257eee37-ab8d-4f4f-a03f-84817d1d136c\",\"text\":\"Des clients majeurs ont-ils réduit ou arrêté leurs commandes ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"eadae478-2cbd-4acf-aaea-235b6b9c6ec6\",\"text\":\"Précisez les clients concernés et le plan d\'action commercial\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"257eee37-ab8d-4f4f-a03f-84817d1d136c\",\"triggerValues\":[\"yes\"]}}]},{\"id\":\"a585a9ed-a808-468f-b895-fe1813708806\",\"label\":\"Ordres de fabrication et sorties matière\",\"questions\":[{\"id\":\"0631b036-3770-424b-adde-94081c0e105e\",\"text\":\"Les ordres de fabrication et bons de sortie matière première sont-ils tous enregistrés et cohérents ?\",\"type\":\"SCALE\",\"weight\":3,\"required\":true},{\"id\":\"648a67e5-6340-4cfd-a0d7-25b09aa480b9\",\"text\":\"Précisez les écarts ou retards de saisie constatés et la cause (absence, surcharge…)\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"0631b036-3770-424b-adde-94081c0e105e\",\"triggerValues\":[\"rarely\",\"never\"]}}]},{\"id\":\"6854eb60-b499-4ae7-82d0-308aa1948ecd\",\"label\":\"État des machines et moules\",\"questions\":[{\"id\":\"d280e04c-de6d-4f7f-9fac-734fcc0323ec\",\"text\":\"Les machines et moules sont-ils en bon état de fonctionnement ?\",\"type\":\"SCALE\",\"weight\":3,\"required\":true},{\"id\":\"13f787b7-b0c6-40ac-9b89-f8ad973d64b1\",\"text\":\"Détail des pannes constatées (machine, pièce, durée) et plan d\'action\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"d280e04c-de6d-4f7f-9fac-734fcc0323ec\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"e7a19efa-6525-4179-956e-197447c07627\",\"text\":\"Nombre de machines à l\'arrêt lors de la visite\",\"type\":\"NUMBER\",\"weight\":1,\"required\":false}]},{\"id\":\"540542c5-cd89-4db1-854c-f450aa1a21c6\",\"label\":\"Inventaire matières premières\",\"questions\":[{\"id\":\"50dee82e-5c9c-4cbb-b000-e609b4e9934c\",\"text\":\"Le stock physique de matières premières correspond-il aux données système ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"2d8acdf3-ef3c-472f-bb16-5bc54b4beda9\",\"text\":\"Précisez les articles et quantités en écart\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"50dee82e-5c9c-4cbb-b000-e609b4e9934c\",\"triggerValues\":[\"no\"]}}]},{\"id\":\"4d8fc23f-d5e2-41ea-8899-44edb0da6b2a\",\"label\":\"Rebuts et déchets\",\"questions\":[{\"id\":\"88da4dbb-1073-467e-b888-028b28f20261\",\"text\":\"Le taux de rebuts constaté est-il dans la norme attendue ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"fe5b0504-e974-4bec-919f-8ba8b3b6e794\",\"text\":\"Taux de rebuts constaté (%)\",\"type\":\"NUMBER\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"88da4dbb-1073-467e-b888-028b28f20261\",\"triggerValues\":[\"no\"]}},{\"id\":\"420add9c-87b9-49c0-8f6c-652d8d55f13e\",\"text\":\"Le stock de déchets à vendre est-il suivi et écoulé régulièrement ?\",\"type\":\"SCALE\",\"weight\":1,\"required\":true}]},{\"id\":\"959ab426-0fdd-422b-9861-b25ab55804ae\",\"label\":\"Suivi balance client et recouvrement\",\"questions\":[{\"id\":\"4ea803ad-635b-4f4b-9d95-dd042d423464\",\"text\":\"Les créances clients sont-elles suivies et à jour ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"adb4ed1e-ce5f-4edb-8814-54035b176520\",\"text\":\"Montant total des impayés significatifs constatés (DT)\",\"type\":\"NUMBER\",\"weight\":1,\"required\":false},{\"id\":\"993736da-e675-48b7-9a9c-adcd7797e8ff\",\"text\":\"Plan d\'action de recouvrement proposé\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"4ea803ad-635b-4f4b-9d95-dd042d423464\",\"triggerValues\":[\"rarely\",\"never\"]}}]},{\"id\":\"49c88fd2-ebe1-4af8-8a34-228a42980734\",\"label\":\"Organisation et climat social\",\"questions\":[{\"id\":\"9e75b12a-efeb-4c33-8bf3-246636cc03d4\",\"text\":\"Les effectifs (production, administratif) sont-ils suffisants ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"0abfee80-5cc4-40ac-91b0-c6b73bb37526\",\"text\":\"Précisez les postes en tension et les recommandations\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"9e75b12a-efeb-4c33-8bf3-246636cc03d4\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"27073984-4a1c-4aec-bf8e-d2ed9abb29bf\",\"text\":\"Un conflit ou climat social tendu a-t-il été observé ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"cf884b88-a902-41e7-9c52-57e6c6acb5f2\",\"text\":\"Détail du conflit constaté et mesures recommandées\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"27073984-4a1c-4aec-bf8e-d2ed9abb29bf\",\"triggerValues\":[\"yes\"]}}]},{\"id\":\"2830c378-e289-4c9f-8972-1becf0694c09\",\"label\":\"Hygiène, sécurité et environnement usine\",\"questions\":[{\"id\":\"435afa32-ba48-4e9b-b9af-74d399e41a9c\",\"text\":\"L\'état de propreté de l\'usine est-il satisfaisant ?\",\"type\":\"SCALE\",\"weight\":1,\"required\":true},{\"id\":\"7baba89c-7da2-45c5-a858-2ffe3542ebf2\",\"text\":\"Les équipements de sécurité (extincteurs, caméras) sont-ils opérationnels et à jour ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"57791061-b2da-44e2-9d11-00a1598c9022\",\"text\":\"Précisez les anomalies constatées et les actions correctives\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"7baba89c-7da2-45c5-a858-2ffe3542ebf2\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"c9b53296-308c-4e40-bab0-02c6653a1e7a\",\"text\":\"Le matériel informatique (postes, imprimantes) est-il suffisant et fonctionnel ?\",\"type\":\"SCALE\",\"weight\":1,\"required\":true}]}]',0,'SUP-0001','Administrateur Audit','2026-10-21T10:30:11.466Z','2026-10-21T10:30:11.466Z','usine'),
('9843be76-2f8c-4557-b8b2-774465dd7596','Audit logistique et commercial — Dépôt','Trame standard pour les audits dépôt : inventaire stock, clôture de caisse, facturation/livraison, retours clients, organisation et recouvrement. Dupliquez-le pour créer un nouveau formulaire à partir de cette base.','[{\"id\":\"b7d2b85e-d5e1-45e8-8ad2-cb728599a9df\",\"label\":\"Inventaire stock dépôt\",\"questions\":[{\"id\":\"b2a0c496-f069-4e1e-a88a-12c1284648d4\",\"text\":\"Le stock physique correspond-il au stock système (PROXIM/PROMOFOOD/BEESKY) ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"4565c091-dac5-4745-af8e-ecbe55cc244d\",\"text\":\"Précisez la nature et la valeur de l\'écart constaté (article, quantité, montant)\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"b2a0c496-f069-4e1e-a88a-12c1284648d4\",\"triggerValues\":[\"no\"]}},{\"id\":\"3b265a76-e443-4911-9a7a-220a10f37611\",\"text\":\"Des articles endommagés ou périmés ont-ils été identifiés ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"35cde7de-9e13-4500-9399-911695e1e3df\",\"text\":\"Détail des articles concernés et prix de liquidation proposé\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"3b265a76-e443-4911-9a7a-220a10f37611\",\"triggerValues\":[\"yes\"]}},{\"id\":\"98254c67-7e91-42e3-898f-f56f591af3a9\",\"text\":\"Les mouvements de stock (transferts entre dépôts, gestes commerciaux) sont-ils tracés formellement ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"4429f7e1-2460-4512-b214-dc2fcf3dcb15\",\"text\":\"Précisez les manques de traçabilité constatés\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"98254c67-7e91-42e3-898f-f56f591af3a9\",\"triggerValues\":[\"rarely\",\"never\"]}}]},{\"id\":\"50835a42-5503-49f2-b183-b563835d5d63\",\"label\":\"Clôture de caisse et inventaire véhicule (agents commerciaux)\",\"questions\":[{\"id\":\"a6ce5277-b220-4c48-95f1-3b9021dda6ae\",\"text\":\"Un écart a-t-il été constaté entre le système (NOMADIS) et les espèces encaissées ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"f0b4188f-c74d-4f6f-8893-bde3e100cdc5\",\"text\":\"Montant de l\'écart constaté (DT)\",\"type\":\"NUMBER\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"a6ce5277-b220-4c48-95f1-3b9021dda6ae\",\"triggerValues\":[\"yes\"]}},{\"id\":\"5d1bde96-3368-4e3d-8bd3-6514a8251a59\",\"text\":\"Un justificatif a-t-il été présenté par l\'agent ?\",\"type\":\"YES_NO\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"a6ce5277-b220-4c48-95f1-3b9021dda6ae\",\"triggerValues\":[\"yes\"]}},{\"id\":\"d2e6a5f3-2ee7-436c-b98f-76e24dca8591\",\"text\":\"L\'écart a-t-il été régularisé immédiatement ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"a6ce5277-b220-4c48-95f1-3b9021dda6ae\",\"triggerValues\":[\"yes\"]}},{\"id\":\"55f04949-4300-4ddd-9672-99f4f1f8b481\",\"text\":\"Un écart a-t-il été constaté lors de l\'inventaire du stock véhicule ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"79ea4bb6-27c7-4aa5-ba02-b39112b28aff\",\"text\":\"Montant/quantité de l\'écart et régularisation effectuée\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"55f04949-4300-4ddd-9672-99f4f1f8b481\",\"triggerValues\":[\"yes\"]}}]},{\"id\":\"0a4c5ae4-aea5-4a90-9156-d8583eeb74f2\",\"label\":\"Facturation, livraison et retours clients\",\"questions\":[{\"id\":\"ce714bf8-0320-4740-b75c-d29c5d38a66a\",\"text\":\"Les livraisons sont-elles systématiquement facturées avant sortie de marchandise ?\",\"type\":\"SCALE\",\"weight\":3,\"required\":true},{\"id\":\"5818dbac-cf5f-45a0-a5f4-e4dfbe75dcdf\",\"text\":\"Précisez les cas de livraison sans facturation préalable et la régularisation effectuée\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"ce714bf8-0320-4740-b75c-d29c5d38a66a\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"4f749bfa-8802-4ac7-8ce0-59b2941d1aee\",\"text\":\"Les remises accordées sont-elles validées officiellement avant application ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"ebfec625-5782-4296-9533-70a9b5e453c2\",\"text\":\"Les retours clients sont-ils traités selon la procédure (déclaration, validation direction) ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"83f7a519-5f6f-40be-a5e8-36977484996e\",\"text\":\"Précisez les retours en attente et l\'origine du blocage\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"ebfec625-5782-4296-9533-70a9b5e453c2\",\"triggerValues\":[\"rarely\",\"never\"]}}]},{\"id\":\"8adce5ac-48e0-4db6-837d-5d852a2f97e2\",\"label\":\"Organisation et ressources humaines\",\"questions\":[{\"id\":\"6365119f-599e-4232-8b46-44d560e2016f\",\"text\":\"Les effectifs administratifs sont-ils suffisants pour les tâches du dépôt ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"24ae309f-3bae-4302-95bb-e868a32a3c91\",\"text\":\"Précisez les tâches impactées et les recommandations (recrutement, réorganisation…)\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"6365119f-599e-4232-8b46-44d560e2016f\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"2da4c42f-8ca0-42e5-8b3d-bf7b10082da7\",\"text\":\"Un organigramme clair et une répartition des tâches sont-ils en place ?\",\"type\":\"YES_NO\",\"weight\":1,\"required\":true}]},{\"id\":\"4d641dd1-cab9-4eec-949a-2be4d798b528\",\"label\":\"Suivi balance client, recouvrement et effets\",\"questions\":[{\"id\":\"b100764a-5296-40d9-b8b1-bc4845158693\",\"text\":\"Les créances clients sont-elles suivies et à jour ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"5ebe2b8d-7664-41d3-ba8e-f346303638d7\",\"text\":\"Montant total des impayés significatifs constatés (DT)\",\"type\":\"NUMBER\",\"weight\":1,\"required\":false},{\"id\":\"19c2973e-63bb-47c2-a106-e4ee15611c42\",\"text\":\"Plan d\'action de recouvrement proposé\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"b100764a-5296-40d9-b8b1-bc4845158693\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"398fa64b-2b69-4d67-a690-d071a14ac914\",\"text\":\"La gestion des effets (traites, échéances) est-elle rigoureuse et à jour ?\",\"type\":\"SCALE\",\"weight\":1,\"required\":true}]}]',0,'SUP-0001','Administrateur Audit','2026-10-21T10:30:11.469Z','2026-10-21T10:30:11.469Z','depot');
